const FILTERS = [
  { id: "all", label: "Все" },
  { id: "hot", label: "Покупали / активные" },
  { id: "samara", label: "Город Самара" },
  { id: "tlt", label: "Тольятти" },
  { id: "plant", label: "Заводы" },
  { id: "end", label: "Крупные заказчики" },
  { id: "lead", label: "Потенциал" },
] as const;

type FilterId = (typeof FILTERS)[number]["id"];

function matches(c: Client, f: FilterId): boolean {
  if (f === "all") return true;
  if (f === "hot") return c.status === "покупал 2024–2026" || c.status === "активный 2026";
  if (f === "samara") return c.city === "Самара";
  if (f === "tlt") return c.city === "Тольятти";
  if (f === "plant") return c.role === "Завод";
  if (f === "lead") return c.status === "потенциал";
  if (f === "end") {
    const n = c.name.toUpperCase();
    return (
      n.includes("АВТОВАЗ") ||
      n.includes("АЗОТ") ||
      n.includes("НПЗ") ||
      n.includes("САМАРАНЕФТЕГАЗ") ||
      n.includes("ТЯЖМАШ") ||
      n.includes("КАУЧУК") ||
      n.includes("ЭЛЕКТРОЩИТ") ||
      n.includes("ТРАНСФОРМАТОР")
    );
  }
  return true;
}

function rowTone(status: string): "success" | "info" | "warning" | undefined {
  if (status === "покупал 2024–2026") return "success";
  if (status === "активный 2026") return "info";
  if (status === "потенциал") return "warning";
  return undefined;
}

